// spec: specs/delivery.md §7 · кейс .qa/tests/delivery/dlv-11-rejected-order-delivery-block.md
// seed: tests/seed.admin.spec.ts (+ rep.json для теста נציג)
// #7e2789 (עבר QA 25.10): в карточке ОТКЛОНЁННОГО заказа блок «משלוח» показывает только «נדחתה» / «ההזמנה נדחתה» —
// нет кнопок, полей, select, «טרם אושרה», «יש לאשר את ההזמנה…», «סמן כמוכנ…», «שמירת שיבוץ».
// Регресс (#6a7491c7, #6a71f0ec): у ожидающего заказа — неактивные поля + «ההזמנה טרם אושרה»; у утверждённого — назначение водителя активно.
// Только чтение: заказы берутся динамически из /orders (вкладка «נדחו», фильтр «שלב ההזמנה»), номера не хардкодятся, ничего не сохраняется.
import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

const rows = (page: Page) => page.getByRole('button', { name: /^#\d+ / });
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');
/** Блок «משלוח» карточки заказа: ближайший предок заголовка, содержащий текст состояния. */
const shipBlock = (page: Page, marker: string): Locator =>
  page.getByRole('heading', { level: 3, name: 'משלוח' }).locator(`xpath=ancestor::*[contains(normalize-space(.), "${marker}")][1]`);

async function openOrdersAll(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
  await expect(rows(page).first()).toBeVisible({ timeout: 30_000 });
}

/** Открывает первый отклонённый заказ клиента «test» из вкладки «נדחו»; возвращает номер или null. */
async function openFirstRejected(page: Page): Promise<string | null> {
  await openOrdersAll(page);
  await page.getByRole('button', { name: /^נדחו \d+$/ }).click();
  const mine = page.getByRole('button', { name: /^#\d+ test / });
  await expect(mine.first().or(page.getByText(/אין הזמנות|לא נמצאו הזמנות/).first())).toBeVisible({ timeout: 20_000 });
  if (!(await mine.count())) return null;
  const no = ((await mine.first().getAttribute('aria-label')) ?? (await mine.first().innerText())).match(/#(\d+)/)![1];
  await mine.first().click();
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  return no;
}

/** Открывает первый заказ с выбранным этапом (фильтр «שלב ההזמנה»); возвращает true, если такой есть. */
async function openFirstByStage(page: Page, stage: string, client = 'test'): Promise<boolean> {
  await openOrdersAll(page);
  await page.getByRole('button', { name: 'סינון' }).click();
  await page.getByRole('combobox', { name: 'שלב ההזמנה' }).selectOption({ label: stage });
  const mine = page.getByRole('button', { name: new RegExp(`^#\\d+ ${client} `) });
  await expect(mine.first().or(page.getByText('לא נמצאו הזמנות התואמות לסינון'))).toBeVisible({ timeout: 20_000 });
  if (!(await mine.count())) return false;
  await mine.first().click();
  await expect(page).toHaveURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  await expect(page.getByRole('heading', { level: 1, name: /^הזמנה #\d+/ })).toBeVisible({ timeout: 30_000 });
  return true;
}

/** Проверки #7e2789 на открытой карточке отклонённого заказа. */
async function expectRejectedShipBlock(page: Page) {
  await expect(header(page)).toContainText('נדחתה');
  const main = page.getByRole('main');
  // только информация об отклонении (источник: «מה רצוי» — «רק שההזמנה נדחתה»)
  await expect(main.getByText('ההזמנה נדחתה').first()).toBeVisible({ timeout: 20_000 });
  const block = shipBlock(page, 'ההזמנה נדחתה');
  await expect(block).toContainText('נדחתה');
  // нет кнопок / полей / select в блоке «משלוח»
  await expect(block.getByRole('button')).toHaveCount(0);
  await expect(block.getByRole('combobox')).toHaveCount(0);
  await expect(block.getByRole('textbox')).toHaveCount(0);
  // нет призыва утвердить, «טרם אושרה», кнопок доставки и שיבוץ — на всей карточке
  await expect(main.getByText('ההזמנה טרם אושרה')).toHaveCount(0);
  await expect(main.getByText(/יש לאשר את ההזמנה/)).toHaveCount(0);
  await expect(main.getByRole('button', { name: /סמן כמוכנ/ })).toHaveCount(0);
  await expect(main.getByRole('button', { name: 'שמירת שיבוץ' })).toHaveCount(0);
  await expect(main.getByRole('combobox', { name: 'נהג' })).toHaveCount(0);
  await expect(main.getByText(/ניתן לשייך נהג/)).toHaveCount(0);
}

test.describe('delivery — הזמנה שנדחתה: בבלוק «משלוח» רק «נדחתה» (#7e2789)', () => {
  test('מפיץ: הזמנה שנדחתה — «ההזמנה נדחתה», בלי שיבוץ, בלי «טרם אושרה» ובלי «סמן כמוכנה» #7e2789 @desktop @prod-safe', async ({ page }) => {
    const no = await openFirstRejected(page);
    test.skip(!no, 'у клиента «test» нет отклонённых заказов');
    await expectRejectedShipBlock(page);
  });

  test('מפיץ 390: אותה הזמנה שנדחתה — בלי שיבוץ ובלי «טרם אושרה» #7e2789 @iphone @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    const no = await openFirstRejected(page);
    test.skip(!no, 'у клиента «test» нет отклонённых заказов');
    await expectRejectedShipBlock(page);
  });

  test('נציג (testtest): הזמנה שנדחתה של הלקוח שלו — אותו בלוק «משלוח» #7e2789 @desktop @prod-safe', async ({ browser }) => {
    const ctx = await browser.newContext({ storageState: auth('rep'), baseURL: test.info().project.use.baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const rep = await ctx.newPage();
    try {
      const no = await openFirstRejected(rep);
      test.skip(!no, 'у rep нет отклонённых заказов клиента «test»');
      await expectRejectedShipBlock(rep);
    } finally {
      await ctx.close();
    }
  });

  test('רגרסיה: הזמנה ממתינה — שדות השיבוץ לא פעילים ו«ההזמנה טרם אושרה» #7e2789 #6a7491c7 @desktop @prod-safe', async ({ page }) => {
    const found = await openFirstByStage(page, 'ממתינה לאישור', '[^ ]+');
    test.skip(!found, 'нет заказов «ממתינה לאישור»');
    const block = shipBlock(page, 'ההזמנה טרם אושרה');
    await expect(block.getByText('ההזמנה טרם אושרה')).toBeVisible({ timeout: 20_000 });
    await expect(block.getByRole('combobox', { name: 'נהג' })).toBeDisabled();
    await expect(block.getByRole('textbox', { name: 'תאריך אספקה' })).toBeDisabled();
    await expect(page.getByText('יש לאשר את ההזמנה לפני עדכון סטטוס המשלוח.')).toBeVisible();
    await expect(page.getByRole('button', { name: 'סמן כמוכנה למשלוח' })).toBeDisabled();
  });

  test('רגרסיה: הזמנה מאושרת — שיוך נהג פעיל (בלי שמירה) #7e2789 #6a7491c7 @desktop @prod-safe', async ({ page }) => {
    const found = await openFirstByStage(page, 'ממתינה לליקוט');
    test.skip(!found, 'нет утверждённых заказов клиента «test» на этапе «ממתינה לליקוט»');
    const block = shipBlock(page, 'שמירת שיבוץ');
    await expect(block.getByRole('combobox', { name: 'נהג' })).toBeVisible({ timeout: 20_000 });
    test.skip((await block.getByText('ללקוח אין כתובת משלוח').count()) > 0, 'у клиента нет адреса — назначение заблокировано (D-25)');
    await expect(block.getByRole('combobox', { name: 'נהג' })).toBeEnabled();
    await expect(block.getByRole('textbox', { name: 'תאריך אספקה' })).toBeEnabled();
    await expect(block.getByText('ההזמנה טרם אושרה')).toHaveCount(0);
    await expect(block.getByText('ההזמנה נדחתה')).toHaveCount(0);
  });
});
